import React, { Component} from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Box,
  Button,
  Heading,
  Grommet,
  FormField,
  Form,
  CheckBox,
  Text
} from 'grommet';
import { Home as HomeIcon, User, Lock, Login } from 'grommet-icons';

import './App.css';

const theme = {
  global: {
    colors: {
      brand: {
        dark: '#667eea',
        light: '#764ba2'
      },
      focus: '#4A90E2',
      text: {
        dark: '#2c3e50',
        light: '#ffffff'
      },
      background: {
        light: '#f8f9fa',
        dark: '#2c3e50'
      }
    },
    font: {
      family: '"Segoe UI", Tahoma, Geneva, Verdana, sans-serif',
      weight: 400
    }
  },
  button: {
    border: {
      radius: '8px'
    },
    primary: {
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      color: 'white'
    }
  },
  formField: {
    border: {
      radius: '8px'
    }
  }
};

const AppBar = (props) => (
  <Box
    className="professional-header"
    pad='medium'
    elevation='medium'
    justify='between'
    direction='row'
    align='center'
    style={{ 
      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
      boxShadow: '0 2px 20px rgba(102, 126, 234, 0.3)'
    }}
    {...props}
  >
    <Box direction="row" align="center" gap="medium" className="header-content">
      <HomeIcon className="home-icon" size="large" color="white" />
      <a style={{ color: 'inherit', textDecoration: 'inherit'}} href="/">
        <Heading level='2' margin='none' className="hms-title" color="white" weight="600">
          Hospital Management System
        </Heading>
      </a>
    </Box>
  </Box>
);

function LogInWrapper() {
    const navigate = useNavigate();
    return <LogIn navigate={navigate} />;
}

class LogIn extends Component {
  state = { isDoctor: false }

  constructor(props) {
    super(props);
    this.routeChange = this.routeChange.bind(this);
  }

  routeChange() {
    let path = '/Home';
    this.props.navigate(path);
  }

  render() {
    const { isDoctor } = this.state; // If doctor, will query from doctor table

    return (
      <Grommet theme={theme} full>
        <Box fill style={{ background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)' }}>
          <AppBar />
          <Box
            fill
            align="center"
            justify="center"
            pad="medium">
            <Box className="modern-form" elevation="medium" round="medium" background="white">
              <Box align="center" margin={{ bottom: 'medium' }}>
                <Login size="xlarge" color="brand.dark" />
                <Heading level='2' margin={{ top: 'small', bottom: 'none' }} color="text.dark">
                  Welcome Back
                </Heading>
                <Text color="text.light" textAlign="center">
                  Please sign in to access your account
                </Text>
              </Box>
              
              <Form
                onReset={event => console.log(event)}
                onSubmit={({ value }) => {
                  console.log("Submit", value);
                  if (value.isDoc === true) {
                    fetch("http://localhost:3001/checkDoclogin?email=" + value.email +
                      "&password=" + value.password)
                      .then(res => res.json())
                      .then(res => {
                        if (res.data.length === 0) {
                          window.alert("Invalid Log In");
                        } else {
                          window.location = "DocHome";
                          console.log(res.data);
                        }
                      });
                  } else {
                    fetch("http://localhost:3001/checklogin?email=" + value.email +
                      "&password=" + value.password)
                      .then(res => res.json())
                      .then(res => {
                        if (res.data.length === 0) {
                          window.alert("Invalid Log In");
                        } else {
                          window.location = "/Home";
                          console.log(res.data);
                        }
                      });
                  }
                }}>
                
                <Box gap="medium">
                  <FormField
                    label="Email Address"
                    name="email"
                    type="email"
                    placeholder="Enter your email"
                    required
                    icon={<User color="brand.dark" />}
                  />
                  <FormField
                    label="Password"
                    type='password'
                    name="password"
                    placeholder="Enter your password"
                    required
                    icon={<Lock color="brand.dark" />}
                  />
                  <FormField
                    component={CheckBox}
                    checked={isDoctor}
                    label="I'm a doctor"
                    name="isDoc"
                    onChange={(event) => {
                      this.setState({ isDoctor: event.target.checked })
                    }}
                  />
                  
                  <Box gap="small" margin={{ top: 'medium' }}>
                    <Button 
                      type="submit" 
                      label="Sign In" 
                      primary 
                      size="large"
                      className="professional-button"
                      fill="horizontal"
                    />
                    <Button 
                      label="Create Account"
                      href="/createAcc"
                      size="large"
                      fill="horizontal"
                      style={{ 
                        border: '2px solid #667eea',
                        color: '#667eea',
                        background: 'transparent'
                      }}
                    />
                  </Box>
                </Box>
              </Form>
            </Box>
          </Box>
        </Box>
      </Grommet>
    );
  }
}
export default LogInWrapper;
